  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C60"],
      "claim": "Colesevelam, a non-absorbed oral agent, has systemic bioavailability <0.04%, supporting negligible oral absorption for locally acting/non-absorbed drugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Testosterone undecanoate, a highly lipophilic long-chain ester, has mean absolute oral bioavailability of 6.8 ± 3.3% in humans, supporting low F for lipophilic ester prodrugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C51"],
      "claim": "Batimastat shows poor oral bioavailability in humans, supporting low F for poorly soluble lipophilic drugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C58"],
      "claim": "Dimethandrolone undecanoate shows poor and inconsistent oral bioavailability, supporting low F for long-chain undecanoate esters.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Tetrabenazine has very low oral systemic availability (mean 0.049), supporting low F for lipophilic drugs with extensive first-pass or presystemic loss.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query molecule is orlistat, a locally acting lipase inhibitor designed to be minimally absorbed; all transferable evidence from non-absorbed and highly lipophilic ester drugs points to very low oral bioavailability, far below the 20% threshold.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for orlistat is present in the provided records.",
    "No record for a beta-lactone lipase inhibitor is available; transfer relies on lipophilic/non-absorbed drug analogies."
  ],
